import subprocess, datetime, sys
E='/workspace/executable'
def gen(vals, path='/tmp/t/kb.log', extra=None):
    start = datetime.date(2021,1,1)
    with open(path,'w') as f:
        for d,v in enumerate(vals):
            day = start + datetime.timedelta(days=d)
            f.write(f'1.2.3.4 - - [{day.strftime("%d/%b/%Y")}:10:00:00 +0000] "GET /a HTTP/1.1" 200 {v} "-" "ua"\n')
            if extra:
                f.write(f'1.2.3.4 - - [{day.strftime("%d/%b/%Y")}:10:00:00 +0000] "GET /b HTTP/1.1" 200 {extra[d]} "-" "ua"\n')
    return path
def trend(vals, extra=None, key='b'):
    gen(vals, extra=extra)
    out = subprocess.run([E, '/tmp/t/kb.log', '--silent-load', '-f', 'p', '-k', key], capture_output=True, text=True, env={'TERM':'xterm','COLUMNS':'150'}).stdout
    for line in out.split('\n'):
        if '│/a ' in line: return line.split('│')[6].strip()
    return out
def score(t): return t.count('➚') - t.count('➘')
def mk(e, h, r, t):
    return [e]*18 + [h]*2 + [r]*18 + [t]*2
def find_ratio(level, h=10**9, lo=0, hi=None):
    # ratio = t/h ; find threshold t for level
    if hi is None: hi = 100*h
    if level>0:
        while hi-lo>1:
            mid=(lo+hi)//2
            if score(trend(mk(1000,h,1000,mid)))>=level: hi=mid
            else: lo=mid
        return hi/h
    else:
        lo=1; hi=h
        if score(trend(mk(1000,h,1000,lo)))>level: return None
        while hi-lo>1:
            mid=(lo+hi)//2
            if score(trend(mk(1000,h,1000,mid)))<=level: lo=mid
            else: hi=mid
        return lo/h
if __name__=='__main__':
    print(trend(mk(1000,1000,1000,1000)), trend(mk(1000,1000,1000,2000)), trend(mk(1000,1000,1000,10000)), trend(mk(1000,1000,1000,100)))
EOF
python3 kb.py"}

