def score(t): return t.count('➚') - t.count('➘')
R=10**9
def fr(level, bc):
    mk = lambda t: [1000]*18+[1000]*2+[R]*18+[t]*2
    if level>0:
        lo, hi = 0, 1000*R
        while hi-lo>1:
            mid=(lo+hi)//2
            if score(trend(mk(mid), bc))>=level: hi=mid
            else: lo=mid
        return hi/R
    else:
        lo, hi = 1, R
        while hi-lo>1:
            mid=(lo+hi)//2
            if score(trend(mk(mid), bc))<=level: lo=mid
            else: hi=mid
        return lo/R
