    idx: usize,
    text: String,
    width: usize,
    blank: bool,
}

fn tokenize(composite: &Composite) -> Vec<Token> {
    let mut tokens: Vec<Token> = Vec::new();
    for (idx, compound) in composite.iter().enumerate() {
        let mut cur: Option<Token> = None;
        for c in compound.text.chars() {
            let blank = c.is_whitespace() && !compound.code;
            let w = char_width(c);
            if let Some(t) = cur.as_mut() {
                if t.blank == blank {
                    t.text.push(c);
                    t.width += w;
                    continue;
                }
            }
            if let Some(t) = cur.take() {
                tokens.push(t);
            }
            cur = Some(Token { idx, text: c.to_string(), width: w, blank });
        }
        if let Some(t) = cur.take() {
            tokens.push(t);
        }
    }
    tokens
}

fn push_piece(line: &mut Line, idx: usize, text: &str, style: Style) {
    if let Some(last) = line.last_mut() {
        if last.idx == idx {
            last.text.push_str(text);
            return;
        }
    }
    line.push(Piece { idx, text: text.to_string(), style });
}

/// Wrap a composite into lines fitting the given width
pub fn wrap(composite: &Composite, width: usize) -> Vec<Line> {
    let total = composite_width(composite);
    if total <= width {
        let line: Line = composite
            .iter()
            .enumerate()
            .map(|(idx, c)| Piece { idx, text: c.text.clone(), style: c.style })
            .collect();
        return vec![line];
    }
    let width = width.max(1);
    let tokens = tokenize(composite);
    let mut lines: Vec<Line> = Vec::new();
    let mut line: Line = Vec::new();
    let mut lw = 0;
    for token in tokens {
        let style = composite[token.idx].style;
        if lw + token.width <= width {
            push_piece(&mut line, token.idx, &token.text, style);
            lw += token.width;
            continue;
        }
        if token.blank {
            // blank which doesn't fit: we skip it
            lines.push(std::mem::take(&mut line));
            lw = 0;
            continue;
        }
        if lw > 0 {
            lines.push(std::mem::take(&mut line));
            lw = 0;
        }
        // the token is put at the start of a line, it may need to be cut
        let mut rest: &str = &token.text;
        loop {
            let rw = str_width(rest);
            if rw <= width {
                push_piece(&mut line, token.idx, rest, style);
                lw = rw;
                break;
            }
            // cut at width
            let mut w = 0;
            let mut cut = 0;
            for (i, c) in rest.char_indices() {
                let cw = char_width(c);
                if w + cw > width {
                    cut = i;
                    break;
                }
                w += cw;
                cut = i + c.len_utf8();
            }
            if cut == 0 {
                // can't even place one char
                let c = rest.chars().next().unwrap();
                cut = c.len_utf8();
            }
            push_piece(&mut line, token.idx, &rest[..cut], style);
            lines.push(std::mem::take(&mut line));
            rest = &rest[cut..];
            if rest.is_empty() {
                lw = 0;
                break;
            }
        }
    }
    if !line.is_empty() || lines.is_empty() {
        lines.push(line);
    }
    // remove empty lines at end which could come from skipped blanks
    while lines.len() > 1 && lines.last().map_or(false, |l| l.is_empty()) {
        lines.pop();
    }
    lines
}

pub fn write_line(out: &mut String, line: &Line, colors: bool) {
    for p in line {
        p.style.write(out, &p.text, colors);
    }
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Align {
    Left,
    Center,
    Right,
}

pub struct TableRow {
    pub cells: Vec<Composite>,
    pub aligns: Vec<Align>,
}

pub struct Table {
    pub rows: Vec<TableRow>,
    /// number of header rows (a separator is drawn after them)
    pub header_rows: usize,
    pub border_style: Style,
}

fn ceil_div(a: usize, b: usize) -> usize {
    (a + b - 1) / b
}

/// compute the widths of the columns
pub fn fit_widths(naturals: &[usize], avgs_ceil: &[usize], avail: usize) -> Vec<usize> {
    let n = naturals.len();
    let sum: usize = naturals.iter().sum();
    let mut widths = naturals.to_vec();
    if sum <= avail {
        return widths;
    }
    let floors: Vec<usize> = (0..n)
        .map(|i| naturals[i].min(avgs_ceil[i].max(4)))
        .collect();
    // order: natural width descending, stable
    let mut order: Vec<usize> = (0..n).collect();
    order.sort_by(|&a, &b| naturals[b].cmp(&naturals[a]));
    let slacks: Vec<usize> = (0..n).map(|i| naturals[i] - floors[i]).collect();
    let total_slack: usize = slacks.iter().sum();
    let r = sum - avail;
    if r <= total_slack {
        let mut rem = r;
        for &i in &order {
            if rem == 0 {
                break;
            }
            if slacks[i] == 0 {
                continue;
            }
            let share = ceil_div(r * slacks[i], total_slack).min(slacks[i]).min(rem);
            widths[i] -= share;
            rem -= share;
        }
        // whatever remains (shouldn't happen often)
        for &i in &order {
            if rem == 0 {
                break;
            }
            let can = widths[i] - floors[i];
            let d = can.min(rem);
            widths[i] -= d;
            rem -= d;
        }
        return widths;
    }
    widths = floors.clone();
    let mut rem = r - total_slack;
    for &i in &order {
        if rem == 0 {
            break;
        }
        let can = widths[i].saturating_sub(3);
        let d = can.min(rem);
        widths[i] -= d;
        rem -= d;
    }
    widths
}

impl Table {
    pub fn render(&self, out: &mut String, width: usize, colors: bool) {
        let mut nbcols = self.rows.iter().map(|r| r.cells.len()).max().unwrap_or(0);
        if nbcols == 0 {
            return;
        }
        let nb_rows = self.rows.len();
        let mut naturals = vec![0usize; nbcols];
        let mut sums = vec![0usize; nbcols];
        for row in &self.rows {
            for ic in 0..nbcols {
                let w = row.cells.get(ic).map_or(0, composite_width);
                naturals[ic] = naturals[ic].max(w);
                sums[ic] += w;
            }
        }
        let widths_sum: usize = naturals.iter().sum();
        let widths: Vec<usize> = if widths_sum + nbcols < width {
            naturals.clone()
        } else if nbcols * 4 < width {
            let avgs: Vec<usize> = sums.iter().map(|&s| ceil_div(s, nb_rows)).collect();
            fit_widths(&naturals, &avgs, width - nbcols - 1)
        } else {
            nbcols = (width.saturating_sub(1)) / 4;
            vec![3; nbcols]
        };
        let bs = self.border_style;
        // top
        self.write_rule(out, &widths, '┌', '┬', '┐', colors);
        for (ir, row) in self.rows.iter().enumerate() {
            let mut cell_lines: Vec<Vec<Line>> = Vec::new();
            let mut height = 1;
            for ic in 0..nbcols {
                let lines = match row.cells.get(ic) {
                    Some(c) => wrap(c, widths[ic]),
                    None => vec![Vec::new()],
                };
                height = height.max(lines.len());
                cell_lines.push(lines);
            }
            for il in 0..height {
                bs.write(out, "│", colors);
                for ic in 0..nbcols {
                    let w = widths[ic];
                    let align = row.aligns.get(ic).copied().unwrap_or(Align::Left);
                    match cell_lines[ic].get(il) {
                        Some(line) => {
                            let lw = line_width(line);
                            let space = w.saturating_sub(lw);
                            let (lp, rp) = match align {
                                Align::Left => (0, space),
                                Align::Right => (space, 0),
                                Align::Center => (space / 2, space - space / 2),
                            };
                            out.push_str(&" ".repeat(lp));
                            write_line(out, line, colors);
                            out.push_str(&" ".repeat(rp));
                        }
                        None => {
                            out.push_str(&" ".repeat(w));
                        }
                    }
                    bs.write(out, "│", colors);
                }
                out.push('\n');
            }
            if ir + 1 == self.header_rows && ir + 1 < self.rows.len() {
                self.write_rule(out, &widths, '├', '┼', '┤', colors);
            }
        }
        self.write_rule(out, &widths, '└', '┴', '┘', colors);
    }
    fn write_rule(&self, out: &mut String, widths: &[usize], l: char, m: char, r: char, colors: bool) {
        let bs = self.border_style;
        bs.write(out, &l.to_string(), colors);
        for (i, &w) in widths.iter().enumerate() {
            bs.write(out, &"─".repeat(w), colors);
            if i + 1 < widths.len() {
                bs.write(out, &m.to_string(), colors);
            }
        }
        bs.write(out, &r.to_string(), colors);
        out.push('\n');
    }
}

/// write a paragraph (wrapped composite)
pub fn write_paragraph(out: &mut String, composite: &Composite, width: usize, colors: bool) {
    for line in wrap(composite, width) {
        write_line(out, &line, colors);
        out.push('\n');
    }
}

pub fn write_list_item(out: &mut String, bullet: &Compound, composite: &Composite, width: usize, colors: bool) {
    let bw = str_width(&bullet.text) + 1;
    let inner = width.saturating_sub(bw).max(1);
    for (i, line) in wrap(composite, inner).iter().enumerate() {
        if i == 0 {
            bullet.style.write(out, &bullet.text, colors);
            out.push(' ');
        } else {
            out.push_str(&" ".repeat(bw));
        }
        write_line(out, line, colors);
        out.push('\n');
    }
}

pub fn write_centered(out: &mut String, composite: &Composite, width: usize, colors: bool) {
    for line in wrap(composite, width) {
        let lw = line_width(&line);
        if lw < width {
            out.push_str(&" ".repeat((width - lw) / 2));
        }
        write_line(out, &line, colors);
        out.push('\n');
    }
}
