//! terminal related utilities

use std::process::Command;

fn ioctl_size(fd: i32) -> Option<(u16, u16)> {
    unsafe {
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws) == 0 {
            return Some((ws.ws_col, ws.ws_row));
        }
    }
    None
}

fn tput_value(arg: &str) -> Option<u16> {
    let output = Command::new("tput").arg(arg).output().ok()?;
    let value = output
        .stdout
        .into_iter()
        .filter_map(|b| char::from(b).to_digit(10))
        .fold(0u16, |v, n| v.wrapping_mul(10).wrapping_add(n as u16));
    if value > 0 {
        Some(value)
    } else {
        None
    }
}

/// returns the terminal width, as the original tool determined it
pub fn terminal_width() -> usize {
    // try /dev/tty first, then stdout
    let mut size = None;
    if let Ok(file) = std::fs::File::open("/dev/tty") {
        use std::os::unix::io::AsRawFd;
        size = ioctl_size(file.as_raw_fd());
    } else {
        size = size.or_else(|| ioctl_size(libc::STDOUT_FILENO));
    }
    if let Some((w, _)) = size {
        return w as usize;
    }
    if let (Some(w), Some(_h)) = (tput_value("cols"), tput_value("lines")) {
        return w as usize;
    }
    50
}

pub fn stdout_is_tty() -> bool {
    unsafe { libc::isatty(libc::STDOUT_FILENO) == 1 }
}
