#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Method {
    Get,
    Head,
    Post,
    Put,
    Delete,
    Connect,
    Options,
    Trace,
    Patch,
    Other,
    None,
}

impl Method {
    pub fn from_str(s: &str) -> Self {
        match s {
            "" => Method::None,
            "GET" => Method::Get,
            "HEAD" => Method::Head,
            "POST" => Method::Post,
            "PUT" => Method::Put,
            "DELETE" => Method::Delete,
            "CONNECT" => Method::Connect,
            "OPTIONS" => Method::Options,
            "TRACE" => Method::Trace,
            "PATCH" => Method::Patch,
            "none" => Method::None,
            _ => Method::Other,
        }
    }
    pub fn name(self) -> &'static str {
        match self {
            Method::Get => "GET",
            Method::Head => "HEAD",
            Method::Post => "POST",
            Method::Put => "PUT",
            Method::Delete => "DELETE",
            Method::Connect => "CONNECT",
            Method::Options => "OPTIONS",
            Method::Trace => "TRACE",
            Method::Patch => "PATCH",
            Method::Other => "other",
            Method::None => "none",
        }
    }
}

#[derive(Clone, Debug)]
pub struct LogLine {
    pub remote_addr: String,
    pub date: Date,
    pub time: Time,
    pub method: Method,
    pub path: String,
    pub status: u16,
    pub bytes_sent: u64,
    pub referer: String,
}

const MONTHS: [&str; 12] = [
    "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
];

fn parse_log_date(s: &str) -> Option<(Date, Time)> {
    let day: u8 = s.get(0..2)?.parse().ok()?;
    if day < 1 || day > 31 {
        return None;
    }
    let month_name = s.get(3..6)?;
    let month = MONTHS.iter().position(|&m| m == month_name)? as u8 + 1;
    let year: u16 = s.get(7..11)?.parse().ok()?;
    let hour: u8 = s.get(12..14)?.parse().ok()?;
    if hour > 23 {
        return None;
    }
    let minute: u8 = s.get(15..17)?.parse().ok()?;
    if minute > 59 {
        return None;
    }
    let second: u8 = s.get(18..20)?.parse().ok()?;
    if second > 59 {
        return None;
    }
    Some((Date { year, month, day }, Time { hour, minute, second }))
}

impl LogLine {
    pub fn parse(s: &str) -> Option<LogLine> {
        let addr_end = s.find(' ')?;
        let remote_addr = &s[..addr_end];
        let rest = &s[addr_end..];
        let ds = rest.find('[')? + addr_end + 1;
        let de = s[ds..].find(']')? + ds;
        let (date, time) = parse_log_date(&s[ds..de])?;
        let rs = s[de..].find('"')? + de + 1;
        let re = s[rs..].find('"')? + rs;
        let request = &s[rs..re];
        // after the request
        let after = &s[re + 1..];
        let p1 = after.find(' ')?;
        let after = &after[p1 + 1..];
        let p2 = after.find(' ')?;
        let status: u16 = after[..p2].parse().ok()?;
        let after = &after[p2 + 1..];
        let (bytes_str, after) = match after.find(' ') {
            Some(p3) => (&after[..p3], &after[p3..]),
            None => (after, ""),
        };
        let bytes_sent: u64 = bytes_str.parse().ok()?;
        let q1 = after.find('"')? + 1;
        let q2 = after[q1..].find('"')? + q1;
        let referer = &after[q1..q2];
        let (method, path) = match request.find(' ') {
            Some(i) => {
                let method = Method::from_str(&request[..i]);
                let rest = &request[i + 1..];
                let path = match rest.find(' ') {
                    Some(j) => &rest[..j],
                    None => rest,
                };
                (method, path)
            }
            None => (Method::None, request),
        };
        let path = match path.find('?') {
            Some(q) => &path[..q],
            None => path,
        };
        Some(LogLine {
            remote_addr: remote_addr.to_string(),
            date,
            time,
            method,
            path: path.to_string(),
            status,
            bytes_sent,
            referer: referer.to_string(),
        })
    }
}
