    head: usize,
    tail: usize,
    last_pushed: Token,
    op_count: usize,
    openness: usize,
}

impl BeTree {
    pub fn new() -> Self {
        BeTree {
            atoms: Vec::new(),
            nodes: vec![Node::empty()],
            head: 0,
            tail: 0,
            last_pushed: Token::Nothing,
            op_count: 0,
            openness: 0,
        }
    }
    fn add_child(&mut self, child: Child) {
        let tail = &mut self.nodes[self.tail];
        if let Child::None = tail.left {
            tail.left = child;
        } else {
            tail.right = child;
        }
    }
    pub fn push_atom(&mut self, atom: String) {
        self.last_pushed = Token::Atom;
        self.atoms.push(atom);
        let idx = self.atoms.len() - 1;
        self.add_child(Child::Atom(idx));
    }
    pub fn open_par(&mut self) {
        self.last_pushed = Token::OpeningPar;
        let mut node = Node::empty();
        node.parent = Some(self.tail);
        self.nodes.push(node);
        let idx = self.nodes.len() - 1;
        self.add_child(Child::Node(idx));
        self.tail = idx;
        self.openness += 1;
    }
    pub fn close_par(&mut self) {
        self.last_pushed = Token::ClosingPar;
        if let Some(parent) = self.nodes[self.tail].parent {
            self.tail = parent;
        }
        self.openness = self.openness.saturating_sub(1);
    }
    pub fn push_unary_operator(&mut self, op: BoolOperator) {
        self.last_pushed = Token::Operator;
        self.op_count += 1;
        let node = Node {
            operator: Some(op),
            parent: Some(self.tail),
            left: Child::None,
            right: Child::None,
            unary: true,
        };
        self.nodes.push(node);
        let idx = self.nodes.len() - 1;
        self.add_child(Child::Node(idx));
        self.tail = idx;
    }
    pub fn push_binary_operator(&mut self, op: BoolOperator) {
        self.last_pushed = Token::Operator;
        self.op_count += 1;
        if self.nodes[self.tail].operator.is_none() {
            self.nodes[self.tail].operator = Some(op);
            return;
        }
        let tail = self.tail;
        let parent = self.nodes[tail].parent;
        let node = Node {
            operator: Some(op),
            parent,
            left: Child::Node(tail),
            right: Child::None,
            unary: false,
        };
        self.nodes.push(node);
        let idx = self.nodes.len() - 1;
        self.nodes[tail].parent = Some(idx);
        match parent {
            Some(p) => {
                let pn = &mut self.nodes[p];
                if pn.left == Child::Node(tail) {
                    pn.left = Child::Node(idx);
                } else if pn.right == Child::Node(tail) {
                    pn.right = Child::Node(idx);
                }
            }
            None => {
                self.head = idx;
            }
        }
        self.tail = idx;
    }
    pub fn accept_binary_operator(&self) -> bool {
        matches!(self.last_pushed, Token::Atom | Token::ClosingPar)
    }
    pub fn accept_opening_par(&self) -> bool {
        matches!(self.last_pushed, Token::Nothing | Token::Operator | Token::OpeningPar)
    }
    pub fn accept_closing_par(&self) -> bool {
        matches!(self.last_pushed, Token::Atom | Token::ClosingPar) && self.openness > 0
    }
}

pub struct StrFilter {
    tree: BeTree,
    regexes: Vec<Regex>,
}

fn invalid_pattern(pattern: &str, msg: &str) -> String {
    format!("StrFilter(InvalidPattern({:?}, {:?}))", pattern, msg)
}

impl StrFilter {
    pub fn new(pattern: &str) -> Result<Self, String> {
        let mut tree = BeTree::new();
        if pattern.contains(',') {
            let mut first = true;
            for part in pattern.split(',') {
                let part = part.trim();
                if part.is_empty() {
