                }
            }
        } else {
            let chars: Vec<char> = pattern.chars().collect();
            let mut buf = String::new();
            let n = chars.len();
            let flush = |tree: &mut BeTree, buf: &mut String| {
                if !buf.is_empty() {
                    tree.push_atom(std::mem::take(buf));
                }
            };
            for i in 0..n {
                let c = chars[i];
                let next = if i + 1 < n { Some(chars[i + 1]) } else { None };
                let prev = if i > 0 { Some(chars[i - 1]) } else { None };
                match c {
                    ' ' => {}
                    '!' if buf.is_empty() => {
                        tree.push_unary_operator(BoolOperator::Not);
                    }
                    '&' if next == Some(' ') => {
                        flush(&mut tree, &mut buf);
                        if !tree.accept_binary_operator() {
                            return Err(invalid_pattern(pattern, "unexpected '&'"));
                        }
                        tree.push_binary_operator(BoolOperator::And);
                    }
                    '|' if next == Some(' ') || (prev == Some(' ') && next.is_some()) => {
                        flush(&mut tree, &mut buf);
                        if !tree.accept_binary_operator() {
                            return Err(invalid_pattern(pattern, "unexpected '|'"));
                        }
                        tree.push_binary_operator(BoolOperator::Or);
                    }
                    '(' if next == Some(' ') => {
                        flush(&mut tree, &mut buf);
                        if !tree.accept_opening_par() {
                            return Err(invalid_pattern(pattern, "unexpected opening parenthesis"));
                        }
                        tree.open_par();
                    }
                    ')' if prev == Some(' ') => {
                        flush(&mut tree, &mut buf);
                        if !tree.accept_closing_par() {
                            println!("expr: {:#?}", tree);
                            return Err(invalid_pattern(pattern, "unexpected closing parenthesis"));
                        }
                        tree.close_par();
                    }
                    _ => {
                        buf.push(c);
                    }
                }
            }
            flush(&mut tree, &mut buf);
        }
        let mut regexes = Vec::new();
        for atom in &tree.atoms {
            match Regex::new(atom) {
                Ok(r) => regexes.push(r),
                Err(e) => return Err(format!("StrFilter(InvalidRegex({:?}))", e)),
            }
        }
        Ok(StrFilter { tree, regexes })
    }

    fn eval_child(&self, child: Child, s: &str) -> Option<bool> {
        match child {
            Child::None => None,
            Child::Atom(i) => Some(self.regexes[i].is_match(s)),
            Child::Node(i) => self.eval_node(i, s),
        }
    }

    fn eval_node(&self, idx: usize, s: &str) -> Option<bool> {
        let node = &self.tree.nodes[idx];
        let left = self.eval_child(node.left, s);
        if let Some(op) = node.operator {
            if let Some(left) = left {
                let short = match op {
                    BoolOperator::And => !left,
                    BoolOperator::Or => left,
                    BoolOperator::Not => false,
                };
                if short {
                    return Some(left);
                }
                let right = self.eval_child(node.right, s);
                Some(match (op, right) {
                    (BoolOperator::And, Some(b)) => left & b,
                    (BoolOperator::Or, Some(b)) => left | b,
                    (BoolOperator::Not, None) => !left,
                    _ => panic!("unexpected operator or operands"),
                })
            } else {
                None
            }
        } else {
            left
        }
    }

    pub fn accepts(&self, s: &str) -> bool {
        match self.eval_node(self.tree.head, s) {
            Some(b) => b,
            None => {
                println!("unexpected lack of expr result on {:?}", s);
                false
            }
        }
    }
}
