//! hit filters

use crate::log::{Date, LogLine, Method, Time};
use crate::strfilter::StrFilter;

// ---------------------------------------------------------------- dates

#[derive(Clone, Copy, Debug)]
pub struct DateTime {
    pub date: Date,
    pub time: Option<Time>,
}

fn parse_u8(s: &str) -> Result<u8, String> {
    s.parse::<u8>().map_err(|e| format!("IntExpected({:?})", e))
}
fn parse_u16(s: &str) -> Result<u16, String> {
    s.parse::<u16>().map_err(|e| format!("IntExpected({:?})", e))
}

fn check_date(date: Date) -> Result<Date, String> {
    if date.month < 1 || date.month > 12 {
        return Err(format!("InvalidMonth({})", date.month));
    }
    if date.day < 1 || date.day > 31 {
        return Err(format!("InvalidDay({})", date.day));
    }
    Ok(date)
}

fn check_time(time: Time) -> Result<Time, String> {
    if time.hour > 23 {
        return Err(format!("InvalidHour({})", time.hour));
    }
    if time.minute > 59 {
        return Err(format!("InvalidMinute({})", time.minute));
    }
    if time.second > 59 {
        return Err(format!("InvalidSecond({})", time.second));
    }
    Ok(time)
}

fn tokens(s: &str) -> Vec<&str> {
    s.split(|c: char| !c.is_ascii_digit()).collect()
}

impl DateTime {
    /// parse a date-time, error is in the inner form (eg `InvalidDay(32)`)
    pub fn parse(s: &str, default: Date) -> Result<DateTime, String> {
        let s = s.trim();
        let t = tokens(s);
        let n = t.len();
        let year4 = t[0].len() == 4;
        let (y, m, d, h, mi, se): (Option<&str>, Option<&str>, &str, Option<&str>, Option<&str>, Option<&str>) =
            match n {
                1 => (None, None, t[0], None, None, None),
                2 => (None, Some(t[0]), t[1], None, None, None),
                3 => (Some(t[0]), Some(t[1]), t[2], None, None, None),
                4 => {
                    if year4 {
                        (Some(t[0]), Some(t[1]), t[2], Some(t[3]), None, None)
                    } else {
                        (None, Some(t[0]), t[1], Some(t[2]), Some(t[3]), None)
                    }
                }
                5 => {
                    if year4 {
                        (Some(t[0]), Some(t[1]), t[2], Some(t[3]), Some(t[4]), None)
                    } else {
                        (None, Some(t[0]), t[1], Some(t[2]), Some(t[3]), Some(t[4]))
                    }
                }
                _ => {
                    if year4 {
                        (Some(t[0]), Some(t[1]), t[2], Some(t[3]), Some(t[4]), Some(t[5]))
                    } else {
                        (None, Some(t[0]), t[1], Some(t[2]), Some(t[3]), Some(t[4]))
                    }
                }
            };
        let year = match y {
            Some(y) => parse_u16(y)?,
            None => default.year,
        };
        let month = match m {
            Some(m) => parse_u8(m)?,
            None => default.month,
        };
        let day = parse_u8(d)?;
        let hour = match h {
            Some(h) => Some(parse_u8(h)?),
            None => None,
        };
        let minute = match mi {
            Some(v) => parse_u8(v)?,
            None => 0,
        };
        let second = match se {
            Some(v) => parse_u8(v)?,
            None => 0,
        };
        let date = check_date(Date { year, month, day })?;
        let time = match hour {
            Some(hour) => Some(check_time(Time { hour, minute, second })?),
            None => None,
        };
        Ok(DateTime { date, time })
    }
    fn cmp_hit(&self, date: Date, time: Time) -> std::cmp::Ordering {
        // compare the hit to self (hit - self)
        match self.time {
            None => date.cmp(&self.date),
            Some(t) => (date, time).cmp(&(self.date, t)),
        }
    }
}

pub enum DateFilter {
    Year(u16),
    Month(u16, u8),
    Precise(DateTime),
    After(DateTime),
    Before(DateTime),
    Not(DateTime),
    Range(DateTime, DateTime),
}

fn dt_err(e: String) -> String {
    format!("DateTime({})", e)
}

impl DateFilter {
    pub fn new(pattern: &str, default: Date) -> Result<Self, String> {
        let s = pattern.trim();
        if let Some(rest) = s.strip_prefix('!') {
            return Ok(DateFilter::Not(DateTime::parse(rest, default).map_err(dt_err)?));
        }
        if let Some(rest) = s.strip_prefix('>') {
            return Ok(DateFilter::After(DateTime::parse(rest, default).map_err(dt_err)?));
        }
        if let Some(rest) = s.strip_prefix('<') {
            return Ok(DateFilter::Before(DateTime::parse(rest, default).map_err(dt_err)?));
        }
        if let Some((a, b)) = s.split_once('-') {
            let a = DateTime::parse(a, default).map_err(dt_err)?;
            let b = DateTime::parse(b, default).map_err(dt_err)?;
            return Ok(DateFilter::Range(a, b));
        }
        let t = tokens(s);
        if t.len() == 1 && t[0].len() == 4 {
            return Ok(DateFilter::Year(parse_u16(t[0]).map_err(dt_err)?));
        }
        if t.len() == 2 && t[0].len() == 4 {
            let year = parse_u16(t[0]).map_err(dt_err)?;
            let month = parse_u8(t[1]).map_err(dt_err)?;
            if month < 1 || month > 12 {
                return Err(dt_err(format!("InvalidMonth({})", month)));
            }
            return Ok(DateFilter::Month(year, month));
        }
        Ok(DateFilter::Precise(DateTime::parse(s, default).map_err(dt_err)?))
    }
    pub fn accepts(&self, date: Date, time: Time) -> bool {
        use std::cmp::Ordering::*;
        match self {
            DateFilter::Year(y) => date.year == *y,
            DateFilter::Month(y, m) => date.year == *y && date.month == *m,
            DateFilter::Precise(dt) => dt.cmp_hit(date, time) == Equal,
            DateFilter::Not(dt) => dt.cmp_hit(date, time) != Equal,
            DateFilter::After(dt) => dt.cmp_hit(date, time) == Greater,
            DateFilter::Before(dt) => dt.cmp_hit(date, time) == Less,
            DateFilter::Range(a, b) => {
                a.cmp_hit(date, time) != Less && b.cmp_hit(date, time) != Greater
            }
        }
    }
}

// ---------------------------------------------------------------- time

pub enum TimeFilter {
    After(Time),
    Before(Time),
    Range(Time, Time),
}

fn parse_filter_time(s: &str) -> Result<Time, String> {
    let s = s.trim();
    if s.len() < 2 {
        return Err("UnexpectedEnd".to_string());
    }
    let hs = s.get(0..2).ok_or_else(|| "UnexpectedEnd".to_string())?;
    let hour: u8 = hs.parse().map_err(|e| format!("IntExpected({:?})", e))?;
    if hour > 23 {
        return Err(format!("InvalidHour({})", hour));
    }
    let mut minute = 0;
    if s.len() >= 5 {
        let ms = s.get(3..5).ok_or_else(|| "UnexpectedEnd".to_string())?;
        minute = ms.parse().map_err(|e| format!("IntExpected({:?})", e))?;
        if minute > 59 {
            return Err(format!("InvalidMinute({})", minute));
        }
    }
    Ok(Time { hour, minute, second: 0 })
}

fn tf_err(e: String) -> String {
    format!("TimeFilter(TimeParse({}))", e)
}

impl TimeFilter {
    pub fn new(pattern: &str) -> Result<Self, String> {
        if let Some(rest) = pattern.strip_prefix('>') {
            return Ok(TimeFilter::After(parse_filter_time(rest).map_err(tf_err)?));
        }
        if let Some(rest) = pattern.strip_prefix('<') {
            return Ok(TimeFilter::Before(parse_filter_time(rest).map_err(tf_err)?));
        }
        if let Some((a, b)) = pattern.split_once('-') {
            if !a.trim().is_empty() && !b.trim().is_empty() {
                let a = parse_filter_time(a).map_err(tf_err)?;
                let b = parse_filter_time(b).map_err(tf_err)?;
                return Ok(TimeFilter::Range(a, b));
            }
        }
        Err("TimeFilter(InvalidFormat)".to_string())
    }
    pub fn accepts(&self, time: Time) -> bool {
        match self {
            TimeFilter::After(t) => time > *t,
            TimeFilter::Before(t) => time < *t,
            TimeFilter::Range(a, b) => time >= *a && time <= *b,
        }
    }
}

// ---------------------------------------------------------------- status

enum StatusItem {
    Class(u16),
    Range(u16, u16),
    Single(u16),
}

impl StatusItem {
    fn accepts(&self, s: u16) -> bool {
        match self {
            StatusItem::Class(c) => s / 100 == *c,
            StatusItem::Range(a, b) => s >= *a && s <= *b,
            StatusItem::Single(v) => s == *v,
        }
    }
}

pub struct StatusFilter {
    positives: Vec<StatusItem>,
    negatives: Vec<StatusItem>,
}

fn status_parse(s: &str) -> Result<u16, String> {
    s.parse::<u16>().map_err(|e| format!("StatusFilter(ParseInt({:?}))", e))
}

impl StatusFilter {
    pub fn new(pattern: &str) -> Result<Self, String> {
        let mut positives = Vec::new();
        let mut negatives = Vec::new();
        for part in pattern.split(',') {
            let part = part.trim();
            let (neg, part) = match part.strip_prefix('!') {
                Some(p) => (true, p),
                None => (false, part),
            };
            let item = match part {
                "2xx" => StatusItem::Class(2),
                "3xx" => StatusItem::Class(3),
                "4xx" => StatusItem::Class(4),
                "5xx" => StatusItem::Class(5),
                _ => {
                    if let Some((a, b)) = part.split_once('-') {
                        StatusItem::Range(status_parse(a)?, status_parse(b)?)
                    } else {
                        StatusItem::Single(status_parse(part)?)
                    }
                }
            };
            if neg {
                negatives.push(item);
            } else {
                positives.push(item);
            }
        }
        Ok(StatusFilter { positives, negatives })
    }
    pub fn accepts(&self, s: u16) -> bool {
        if !self.positives.is_empty() && !self.positives.iter().any(|i| i.accepts(s)) {
            return false;
        }
        !self.negatives.iter().any(|i| i.accepts(s))
    }
}

// ---------------------------------------------------------------- method

pub struct MethodFilter {
    method: Method,
    negative: bool,
}

impl MethodFilter {
    pub fn new(pattern: &str) -> Self {
        let s = pattern.trim();
        let (negative, s) = match s.strip_prefix('!') {
            Some(r) => (true, r),
            None => (false, s),
        };
        MethodFilter { method: Method::from_str(s), negative }
    }
    pub fn accepts(&self, m: Method) -> bool {
        (m == self.method) != self.negative
    }
}

// ---------------------------------------------------------------- all

pub enum Filter {
    Date(DateFilter),
    Ip(StrFilter),
    Method(MethodFilter),
    Path(StrFilter),
    Referer(StrFilter),
    Status(StatusFilter),
    Time(TimeFilter),
}

pub struct NamedFilter {
    pub name: &'static str,
    pub pattern: String,
    pub filter: Filter,
}

impl NamedFilter {
    pub fn accepts(&self, line: &LogLine) -> bool {
        match &self.filter {
            Filter::Date(f) => f.accepts(line.date, line.time),
            Filter::Ip(f) => f.accepts(&line.remote_addr),
            Filter::Method(f) => f.accepts(line.method),
            Filter::Path(f) => f.accepts(&line.path),
            Filter::Referer(f) => f.accepts(&line.referer),
            Filter::Status(f) => f.accepts(line.status),
            Filter::Time(f) => f.accepts(line.time),
        }
    }
}
