fn parse_u8(s: &str) -> Result<u8, String> {
    s.parse::<u8>().map_err(|e| format!("IntExpected({:?})", e))
}
fn parse_u16(s: &str) -> Result<u16, String> {
    s.parse::<u16>().map_err(|e| format!("IntExpected({:?})", e))
}

fn check_date(date: Date) -> Result<Date, String> {
    if date.month < 1 || date.month > 12 {
        return Err(format!("InvalidMonth({})", date.month));
    }
    if date.day < 1 || date.day > 31 {
        return Err(format!("InvalidDay({})", date.day));
    }
    Ok(date)
}

fn check_time(time: Time) -> Result<Time, String> {
    if time.hour > 23 {
        return Err(format!("InvalidHour({})", time.hour));
    }
    if time.minute > 59 {
        return Err(format!("InvalidMinute({})", time.minute));
    }
    if time.second > 59 {
        return Err(format!("InvalidSecond({})", time.second));
    }
    Ok(time)
}

fn tokens(s: &str) -> Vec<&str> {
    s.split(|c: char| !c.is_ascii_digit()).collect()
}

impl DateTime {
    /// parse a date-time, error is in the inner form (eg `InvalidDay(32)`)
    pub fn parse(s: &str, default: Date) -> Result<DateTime, String> {
        let s = s.trim();
        let t = tokens(s);
        let n = t.len();
        let year4 = t[0].len() == 4;
        let (y, m, d, h, mi, se): (Option<&str>, Option<&str>, &str, Option<&str>, Option<&str>, Option<&str>) =
            match n {
                1 => (None, None, t[0], None, None, None),
                2 => (None, Some(t[0]), t[1], None, None, None),
                3 => (Some(t[0]), Some(t[1]), t[2], None, None, None),
                4 => {
                    if year4 {
                        (Some(t[0]), Some(t[1]), t[2], Some(t[3]), None, None)
                    } else {
                        (None, Some(t[0]), t[1], Some(t[2]), Some(t[3]), None)
                    }
                }
                5 => {
                    if year4 {
                        (Some(t[0]), Some(t[1]), t[2], Some(t[3]), Some(t[4]), None)
                    } else {
                        (None, Some(t[0]), t[1], Some(t[2]), Some(t[3]), Some(t[4]))
                    }
                }
                _ => {
                    if year4 {
                        (Some(t[0]), Some(t[1]), t[2], Some(t[3]), Some(t[4]), Some(t[5]))
                    } else {
                        (None, Some(t[0]), t[1], Some(t[2]), Some(t[3]), Some(t[4]))
                    }
                }
            };
        let year = match y {
            Some(y) => parse_u16(y)?,
            None => default.year,
        };
        let month = match m {
            Some(m) => parse_u8(m)?,
            None => default.month,
        };
        let day = parse_u8(d)?;
        let hour = match h {
            Some(h) => Some(parse_u8(h)?),
            None => None,
        };
        let minute = match mi {
            Some(v) => parse_u8(v)?,
            None => 0,
        };
        let second = match se {
            Some(v) => parse_u8(v)?,
            None => 0,
        };
        let date = check_date(Date { year, month, day })?;
        let time = match hour {
            Some(hour) => Some(check_time(Time { hour, minute, second })?),
            None => None,
        };
        Ok(DateTime { date, time })
    }
    fn cmp_hit(&self, date: Date, time: Time) -> std::cmp::Ordering {
        // compare the hit to self (hit - self)
        match self.time {
            None => date.cmp(&self.date),
            Some(t) => (date, time).cmp(&(self.date, t)),
        }
    }
}

