//! number formatting

/// format a number with thousands separators
pub fn thousands(n: u64) -> String {
    let s = n.to_string();
    let bytes = s.as_bytes();
    let mut out = String::new();
    for (i, b) in bytes.iter().enumerate() {
        if i > 0 && (bytes.len() - i) % 3 == 0 {
            out.push(',');
        }
        out.push(*b as char);
    }
    out
}

/// format a size in at most 4 chars
pub fn fit_4(n: u64) -> String {
    if n < 10_000 {
        return n.to_string();
    }
    let mut v = n as f64;
    for p in ['K', 'M', 'G', 'T', 'P'] {
        v /= 1000.0;
        let s = format!("{:.1}", v);
        if s.len() <= 3 {
            return format!("{}{}", s, p);
        }
        let s = format!("{:.0}", v);
        if s.len() <= 3 {
            return format!("{}{}", s, p);
        }
    }
    "huge".to_string()
}

pub fn percent(part: u64, total: u64) -> String {
    let p = if total == 0 { 0.0 } else { 100.0 * part as f64 / total as f64 };
    format!("{:.1}%", p)
}
