                Some(&i) => i,
                None => {
                    let i = groups.len();
                    idx.insert(name.clone(), i);
                    groups.push(Group { name, hits: 0, bytes: 0, per_day: vec![0; self.n_days] });
                    i
                }
            };
            let g = &mut groups[i];
            g.hits += 1;
            g.bytes += h.line.bytes_sent;
            g.per_day[h.day] += key_val(&h.line, self.key);
        }
        let key = self.key;
        groups.sort_by(|a, b| b.key(key).cmp(&a.key(key)));
        groups
    }

    fn spark(&self, g: &Group) -> String {
        let n = self.n_days;
        let start = n.saturating_sub(20);
        let vals = &g.per_day[start..n];
        let max = vals.iter().copied().max().unwrap_or(0);
        vals.iter().map(|&v| spark_char(v, max)).collect()
    }

    fn trend(&self, g: &Group) -> Option<TrendInfo> {
        let n = self.n_days;
        if n < 4 {
            return None;
        }
        let w = n.min(20);
        let e: u64 = self.global_per_day[0..w - 2].iter().sum();
        let hh: u64 = self.global_per_day[w - 2..w].iter().sum();
        let r: u64 = g.per_day[n - w..n - 2].iter().sum();
        let t: u64 = g.per_day[n - 2..n].iter().sum();
        let (e, hh, rf, t) = (e as f64, hh as f64, r as f64, t as f64);
        let num = t * e - hh * rf;
        let den = t * e + hh * rf;
        let d = num / den;
        let v = (d * 1000.0) as i32;
        Some(TrendInfo { d, v, r })
    }

    fn trend_cell(&self, g: &Group) -> Composite {
        if g.hits < 10 {
            return Vec::new();
        }
        let v = match self.trend(g) {
            Some(t) => t.v,
            None => return Vec::new(),
        };
        let (n, style, c) = if v > 900 {
            (3, UP, "➚")
        } else if v > 500 {
            (2, UP, "➚")
        } else if v > 200 {
            (1, UP, "➚")
        } else if v < -900 {
            (3, DOWN, "➘")
        } else if v < -500 {
            (2, DOWN, "➘")
        } else if v < -200 {
            (1, DOWN, "➘")
        } else {
            (0, UP, "")
        };
        let mut comp = Vec::new();
        for i in 0..n {
            if i > 0 {
                comp.push(plain(" "));
            }
            comp.push(Compound::new(c, style));
        }
        comp
    }

    /// multi-day table with # and name columns
    fn print_named_multi(&self, out: &mut String, label: &str, groups: &[&Group]) {
        let mut rows = vec![self.header_row(&["#", label, "hits", "bytes", "days", "trend"])];
        for (i, g) in groups.iter().enumerate() {
            rows.push(TableRow {
                cells: vec![
                    vec![plain((i + 1).to_string())],
                    vec![plain(g.name.clone())],
                    self.key_cell(Key::Hits, thousands(g.hits)),
                    self.key_cell(Key::Bytes, fit_4(g.bytes)),
                    vec![italic(self.spark(g))],
                    self.trend_cell(g),
                ],
                aligns: vec![Align::Right, Align::Left, Align::Right, Align::Right, Align::Right, Align::Center],
            });
        }
        self.render_table(out, rows);
    }

    /// few-day table with # and name columns
    fn print_named_few(&self, out: &mut String, label: &str, groups: &[&Group]) {
        let mut rows = vec![self.header_row(&["#", label, "hits", "%", "bytes"])];
        for (i, g) in groups.iter().enumerate() {
            rows.push(TableRow {
                cells: vec![
                    vec![plain((i + 1).to_string())],
                    vec![plain(g.name.clone())],
                    self.key_cell(Key::Hits, thousands(g.hits)),
                    vec![plain(percent(g.hits, self.total_hits))],
                    self.key_cell(Key::Bytes, fit_4(g.bytes)),
                ],
                aligns: vec![Align::Right, Align::Left, Align::Right, Align::Right, Align::Right],
            });
        }
        self.render_table(out, rows);
    }

    /// multi-day table without # (methods & status)
    fn print_unnamed_multi(&self, out: &mut String, label: &str, groups: &[&Group]) {
        let mut rows = vec![self.header_row(&[label, "hits", "%", "bytes", "days", "trend"])];
        for g in groups.iter() {
            rows.push(TableRow {
                cells: vec![
                    vec![plain(g.name.clone())],
                    self.key_cell(Key::Hits, thousands(g.hits)),
                    vec![plain(percent(g.hits, self.total_hits))],
                    self.key_cell(Key::Bytes, fit_4(g.bytes)),
                    vec![italic(self.spark(g))],
                    self.trend_cell(g),
                ],
                aligns: vec![Align::Center, Align::Right, Align::Right, Align::Right, Align::Right, Align::Center],
            });
        }
        self.render_table(out, rows);
    }

    fn print_changes(&self, out: &mut String, name: &str, label: &str, groups: &[Group]) {
        let limit = match self.length {
            0 => 5,
            1 => 10,
            l => 10 * l,
        };
        let mut items: Vec<(&Group, TrendInfo)> = groups
            .iter()
            .filter(|g| g.hits >= 10)
            .filter_map(|g| self.trend(g).map(|t| (g, t)))
            .collect();
        // more popular
        items.sort_by(|a, b| {
            b.1.d.partial_cmp(&a.1.d).unwrap_or(std::cmp::Ordering::Equal).then(b.1.r.cmp(&a.1.r))
        });
        let more: Vec<&Group> = items.iter().take(limit).map(|(g, _)| *g).collect();
        self.print_title(out, &format!("More popular {}", name));
        self.print_named_multi(out, label, &more);
        items.sort_by(|a, b| {
            a.1.d.partial_cmp(&b.1.d).unwrap_or(std::cmp::Ordering::Equal).then(b.1.r.cmp(&a.1.r))
        });
        let less: Vec<&Group> = items.iter().take(limit).map(|(g, _)| *g).collect();
        self.print_title(out, &format!("Less popular {}", name));
        self.print_named_multi(out, label, &less);
    }

    fn print_named_section(
        &self,
        out: &mut String,
        name: &str,
        label: &str,
        groups: Vec<Group>,
        limit: usize,
    ) {
        let count = groups.len();
        let shown: Vec<&Group> = groups.iter().take(limit).collect();
        if self.multi_day() {
            let title = if count > limit {
                format!("{} {}. {} most frequent:", thousands(count as u64), name, limit)
            } else {
                format!("{} {}", thousands(count as u64), name)
            };
            self.print_title(out, &title);
            self.print_named_multi(out, label, &shown);
            if self.changes {
                self.print_changes(out, name, label, &groups);
            }
        } else {
            let mf = if count > limit { format!("{} most frequent:", limit) } else { String::new() };
            self.print_template_title(out, count, name, &mf);
            self.print_named_few(out, label, &shown);
        }
    }

    pub fn print_methods(&self, out: &mut String) {
        let groups = self.groups(|l| Some(l.method.name().to_string()));
        let shown: Vec<&Group> = groups.iter().collect();
        if self.multi_day() {
            self.print_title(out, "methods");
            self.print_unnamed_multi(out, "method", &shown);
        } else {
            self.print_template_title(out, groups.len(), "methods", "");
            self.print_named_few(out, "method", &shown);
        }
        let _ = Method::Get;
    }

    pub fn print_status(&self, out: &mut String) {
        if self.length == 0 {
            let mut counts = [0u64; 4];
            for h in &self.hits {
                let c = h.line.status / 100;
                if (2..=5).contains(&c) {
                    counts[(c - 2) as usize] += 1;
                }
            }
            self.print_title(out, "HTTP status codes:");
            let rows = vec![
                self.header_row(&["2xx", "3xx", "4xx", "5xx"]),
                TableRow {
                    cells: counts.iter().map(|&c| vec![plain(percent(c, self.total_hits))]).collect(),
                    aligns: vec![Align::Center; 4],
                },
            ];
            self.render_table(out, rows);
            return;
        }
        let groups = self.groups(|l| Some(l.status.to_string()));
        let limit = 100;
        let shown: Vec<&Group> = groups.iter().take(limit).collect();
        if self.multi_day() {
            self.print_title(out, "HTTP status codes");
            self.print_unnamed_multi(out, "status", &shown);
        } else {
            self.print_template_title(out, groups.len(), "HTTP status codes", "");
            self.print_named_few(out, "status", &shown);
        }
    }

    pub fn print_ips(&self, out: &mut String) {
        let groups = self.groups(|l| Some(l.remote_addr.clone()));
        let limit = match self.length {
            0 => 3,
            1 => 5,
            l => 10 * l,
        };
        self.print_named_section(out, "remote IP addresses", "IP address", groups, limit);
    }

    pub fn print_referers(&self, out: &mut String) {
        let groups = self.groups(|l| {
            if l.referer == "-" {
                None
            } else {
                Some(l.referer.clone())
            }
        });
        let limit = match self.length {
            0 => 5,
            1 => 10,
            l => 20 * l,
        };
        self.print_named_section(out, "referrers", "referrer", groups, limit);
    }

    pub fn print_paths(&self, out: &mut String) {
        let all = self.all_paths;
        let groups = self.groups(|l| {
            if !all && is_resource(&l.path) {
                None
            } else {
                Some(l.path.clone())
            }
        });
        let limit = match self.length {
            0 => 10,
            l => 50 * l,
        };
        let name = if all { "paths" } else { "paths (excluding resources like images, css, etc.)" };
        self.print_named_section(out, name, "path", groups, limit);
    }
}

