}

#[derive(Clone, Copy, PartialEq, Debug)]
enum Output {
    Tables,
    Raw,
    Csv,
    Json,
}

fn parse_key(s: &str) -> Result<Key, String> {
    match s.to_lowercase().as_str() {
        "h" | "hit" | "hits" => Ok(Key::Hits),
        "b" | "byte" | "bytes" => Ok(Key::Bytes),
        _ => Err(format!("unrecognized key {:?}", s)),
    }
}

fn parse_output(s: &str) -> Result<Output, String> {
    match s.to_lowercase().as_str() {
        "t" | "tables" => Ok(Output::Tables),
        "r" | "raw" => Ok(Output::Raw),
        "c" | "csv" => Ok(Output::Csv),
        "j" | "json" => Ok(Output::Json),
        _ => Err(format!("unrecognized output {:?}", s)),
    }
}

fn parse_length(s: &str) -> Result<usize, String> {
    s.parse::<usize>().map_err(|e| e.to_string())
}

const ALL_FIELDS: [Field; 7] = [
    Field::Date,
    Field::Time,
    Field::Method,
    Field::Status,
    Field::Ip,
    Field::Referer,
    Field::Path,
];
const DEFAULT_FIELDS: [Field; 4] = [Field::Date, Field::Status, Field::Referer, Field::Path];

fn parse_fields(s: &str) -> Result<Vec<Field>, String> {
    let mut fields: Vec<Field> = if s.starts_with('+') || s.starts_with('-') {
        DEFAULT_FIELDS.to_vec()
    } else {
        Vec::new()
    };
    fn add(fields: &mut Vec<Field>, f: Field) {
        fields.retain(|&x| x != f);
        fields.push(f);
    }
    let mut op = '+';
    let mut cur = String::new();
    for c in s.chars().chain(std::iter::once(',')) {
        if c == ',' || c == '+' || c == '-' || c == ' ' {
            if !cur.is_empty() {
                let first = cur.chars().next().unwrap();
                let lf = first.to_ascii_lowercase();
                let fs: Vec<Field> = match lf {
                    'a' => ALL_FIELDS.to_vec(),
                    'd' => vec![Field::Date],
                    't' => vec![Field::Time],
                    'm' => vec![Field::Method],
                    's' => vec![Field::Status],
                    'i' => vec![Field::Ip],
                    'r' => vec![Field::Referer],
                    'p' => vec![Field::Path],
                    _ => return Err(format!("unrecognized field start {:?}", first)),
                };
                for f in fs {
                    if op == '-' {
                        fields.retain(|&x| x != f);
                    } else {
                        add(&mut fields, f);
                    }
                }
                cur.clear();
            }
            op = if c == '-' { '-' } else { '+' };
        } else {
            cur.push(c);
        }
    }
    Ok(fields)
}

fn build_cli() -> Command {
    Command::new("rhit")
        .disable_help_flag(true)
        .disable_version_flag(true)
        .arg(Arg::new("help").long("help").action(ArgAction::SetTrue))
        .arg(Arg::new("version").long("version").action(ArgAction::SetTrue))
        .arg(
