fn is_gz(path: &Path) -> bool {
    path.extension().map_or(false, |e| e == "gz")
}

fn open_reader(path: &Path) -> io::Result<Box<dyn BufRead>> {
    let file = fs::File::open(path)?;
    if is_gz(path) {
        Ok(Box::new(BufReader::new(flate2::read::MultiGzDecoder::new(file))))
    } else {
        Ok(Box::new(BufReader::new(file)))
    }
}

fn first_line(path: &Path) -> io::Result<Option<LogLine>> {
    let mut reader = open_reader(path)?;
    let mut line = String::new();
    let n = reader.read_line(&mut line)?;
    if n == 0 {
        return Ok(None);
    }
    let l = line.trim_end_matches('\n').trim_end_matches('\r');
    Ok(LogLine::parse(l))
}

fn collect_files(path: &Path, check_name: bool, out: &mut Vec<PathBuf>) -> io::Result<()> {
    if path.is_dir() {
        for entry in fs::read_dir(path)? {
            let entry = entry?;
            let p = entry.path();
            if p.is_dir() {
                collect_files(&p, check_name, out)?;
            } else {
                let ok = !check_name
                    || p.file_name().and_then(|n| n.to_str()).map_or(false, |n| n.contains("access.log"));
                if ok {
                    out.push(p);
                }
            }
        }
    } else {
        out.push(path.to_path_buf());
    }
    Ok(())
}

struct Progress {
    silent: bool,
    total: usize,
}

impl Progress {
    fn show(&self, done: usize) {
        if self.silent {
            return;
        }
        let total = self.total.max(1);
        let eighths = ((done as f64) * 320.0 / (total as f64)).round() as usize;
        let mut bar = "█".repeat(eighths / 8);
        let partial = eighths % 8;
        if partial > 0 {
            bar.push(['▏', '▎', '▍', '▌', '▋', '▊', '▉'][partial - 1]);
        }
        let w = str_width(&bar);
        if w < 40 {
            bar.push_str(&" ".repeat(40 - w));
        }
        eprint!(
            "\x1b7\x1b[2K{:>4} / {} \x1b[48;5;5m\x1b[38;5;11m{}\x1b[49m\x1b[39m\x1b8",
            done, self.total, bar
        );
    }
    fn clear(&self) {
        if !self.silent {
            eprint!("\x1b7\x1b[2K\x1b8");
        }
    }
}

fn main() -> Result<(), RhitError> {
    let matches = build_cli().get_matches();
    if matches.get_flag("help") {
        help::print_help(term::terminal_width());
        return Ok(());
    }
    if matches.get_flag("version") {
        println!("rhit 2.0.4");
        return Ok(());
    }
    let key = *matches.get_one::<Key>("key").unwrap();
    let length = *matches.get_one::<usize>("length").unwrap();
    let fields = matches.get_one::<Vec<Field>>("fields").unwrap().clone();
    let output = *matches.get_one::<Output>("output").unwrap();
    let color = matches.get_one::<String>("color").unwrap().clone();
    let silent = matches.get_flag("silent-load");
    let check_name = !matches.get_flag("no-name-check");
    let user_paths: Vec<PathBuf> = matches
        .get_many::<PathBuf>("files")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let default_location = user_paths.is_empty();
    let paths: Vec<PathBuf> = if default_location {
        vec![PathBuf::from("/var/log/nginx")]
    } else {
        user_paths
    };
    // checking paths
    for p in &paths {
        if !p.exists() {
            if default_location {
                eprintln!("No nginx log found at default location, do you have nginx set up?");
                eprintln!("If necessary, provide the path to the log file(s) as argument.");
                eprintln!("More information with 'rhit --help'.");
            }
            return Err(RhitError(format!("PathNotFound({:?})", p)));
        }
    }
    let mut candidates = Vec::new();
    for p in &paths {
        collect_files(p, check_name, &mut candidates)?;
    }
    let mut files: Vec<(PathBuf, Date, Time)> = Vec::new();
    for c in candidates {
        if let Some(line) = first_line(&c)? {
            files.push((c, line.date, line.time));
        }
    }
    if files.is_empty() {
        if default_location {
            eprintln!("No nginx log found at default location, do you have nginx set up?");
            eprintln!("If necessary, provide the path to the log file(s) as argument.");
            eprintln!("More information with 'rhit --help'.");
        }
        return Err(RhitError("NoLogFileFound".to_string()));
    }
    files.sort_by(|a, b| (a.1, a.2).cmp(&(b.1, b.2)));
    let default_date = files[0].1;

    // building filters
    let mut filters: Vec<NamedFilter> = Vec::new();
    if let Some(p) = matches.get_one::<String>("date") {
        let f = DateFilter::new(p, default_date).map_err(RhitError)?;
        filters.push(NamedFilter { name: "date", pattern: p.clone(), filter: Filter::Date(f) });
    }
    if let Some(p) = matches.get_one::<String>("ip") {
        let f = StrFilter::new(p).map_err(RhitError)?;
        filters.push(NamedFilter { name: "remote address", pattern: p.clone(), filter: Filter::Ip(f) });
    }
    if let Some(p) = matches.get_one::<String>("method") {
        let f = MethodFilter::new(p);
        filters.push(NamedFilter { name: "method", pattern: p.clone(), filter: Filter::Method(f) });
    }
    if let Some(p) = matches.get_one::<String>("path") {
        let f = StrFilter::new(p).map_err(RhitError)?;
        filters.push(NamedFilter { name: "path", pattern: p.clone(), filter: Filter::Path(f) });
    }
    if let Some(p) = matches.get_one::<String>("referer") {
        let f = StrFilter::new(p).map_err(RhitError)?;
        filters.push(NamedFilter { name: "referer", pattern: p.clone(), filter: Filter::Referer(f) });
    }
    if let Some(p) = matches.get_one::<String>("status") {
        let f = StatusFilter::new(p).map_err(RhitError)?;
        filters.push(NamedFilter { name: "status", pattern: p.clone(), filter: Filter::Status(f) });
    }
    if let Some(p) = matches.get_one::<String>("time") {
        let f = TimeFilter::new(p).map_err(RhitError)?;
        filters.push(NamedFilter { name: "time", pattern: p.clone(), filter: Filter::Time(f) });
    }

    let colors = match color.as_str() {
        "yes" => true,
        "no" => false,
        _ => term::stdout_is_tty(),
    };

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    let progress = Progress { silent, total: files.len() };
    let mut base = Base::new();
    let mut json_first = true;
    match output {
        Output::Csv => {
            writeln!(out, "date,time,remote address,method,path,status,bytes sent,referer").unwrap();
        }
        Output::Json => {
            write!(out, "[").unwrap();
        }
        _ => {}
    }
    progress.show(0);
    for (i, (path, _, _)) in files.iter().enumerate() {
        let mut reader = open_reader(path)?;
        let mut buf = Vec::new();
        loop {
            buf.clear();
            let n = reader.read_until(b'\n', &mut buf)?;
            if n == 0 {
                break;
            }
            let s = match std::str::from_utf8(&buf) {
                Ok(s) => s,
                Err(_) => {
                    return Err(RhitError::from(io::Error::new(
                        io::ErrorKind::InvalidData,
                        "stream did not contain valid UTF-8",
                    )))
                }
            };
            let s = s.strip_suffix('\n').unwrap_or(s);
            let s = s.strip_suffix('\r').unwrap_or(s);
            let line = match LogLine::parse(s) {
                Some(l) => l,
                None => continue,
            };
            if output == Output::Tables {
                base.push(line);
                continue;
            }
            if !filters.iter().all(|f| f.accepts(&line)) {
                continue;
            }
            match output {
                Output::Raw => {
                    writeln!(out, "{}", s).unwrap();
                }
                Output::Csv => {
                    writeln!(
                        out,
                        "{},{},{},{},\"{}\",{},{},\"{}\"",
                        line.date,
                        line.time,
                        line.remote_addr,
                        line.method.name(),
                        line.path,
                        line.status,
                        line.bytes_sent,
                        line.referer
                    )
                    .unwrap();
                }
                Output::Json => {
                    if json_first {
                        writeln!(out).unwrap();
                    } else {
                        writeln!(out, ",").unwrap();
                    }
                    json_first = false;
                    write!(
                        out,
                        "  {{\n    \"date\": \"{}\",\n    \"time\": \"{}\",\n    \"remote_addr\": \"{}\",\n    \"method\": \"{}\",\n    \"path\": \"{}\",\n    \"status\": \"{}\",\n    \"bytes_sent\": {},\n    \"referer\": \"{}\"\n  }}",
                        line.date,
                        line.time,
                        line.remote_addr,
                        line.method.name(),
                        line.path,
                        line.status,
                        line.bytes_sent,
                        line.referer
                    )
                    .unwrap();
                }
                Output::Tables => {}
            }
        }
        out.flush().unwrap();
        progress.show(i + 1);
    }
    progress.clear();
    if !silent {
        if files.len() == 1 {
            if paths.len() == 1 {
                eprintln!("I've read 1 file in {:?}", paths[0]);
            } else {
                eprintln!("I've read 1 file in {:?}", paths);
            }
        } else if paths.len() == 1 {
            eprintln!("I've read {} files in {:?}", files.len(), paths[0]);
        } else {
            eprintln!("I've read {} files in {:?}", files.len(), paths);
        }
    }
    if output == Output::Json {
        writeln!(out, "\n]").unwrap();
    }
    if output != Output::Tables {
        out.flush().unwrap();
        return Ok(());
    }

    // tables output
    let width = term::terminal_width();
    let mut text = String::new();
    let total_lines = base.hits.len();
    let total_bytes: u64 = base.hits.iter().map(|h| h.line.bytes_sent).sum();
    let mut header: Composite = Vec::new();
    match key {
        Key::Hits => {
            header.push(Compound::new(thousands(total_lines as u64), ITALIC));
            header.push(Compound::plain(format!(" hits and {} from ", fit_4(total_bytes))));
        }
        Key::Bytes => {
            header.push(Compound::plain(format!("{} hits and ", thousands(total_lines as u64))));
            header.push(Compound::new(fit_4(total_bytes), ITALIC));
            header.push(Compound::plain(" from "));
        }
    }
    header.push(Compound::new(base.dates[0].to_string(), BOLD));
    header.push(Compound::plain(" to "));
    header.push(Compound::new(base.dates[base.dates.len() - 1].to_string(), BOLD));
    write_paragraph(&mut text, &header, width, colors);

    let mut hits: Vec<&Hit> = base.hits.iter().collect();
    for f in &filters {
        let before = hits.len();
        hits.retain(|h| f.accepts(&h.line));
        let removed = before - hits.len();
        let pct = 100.0 * removed as f64 / total_lines as f64;
        let comp = vec![
            Compound::plain(format!("Filtering by {} on pattern ", f.name)),
            Compound::code(f.pattern.clone(), CODE),
            Compound::plain(" removed "),
            Compound::new(format!("{:.2}%", pct), BOLD),
            Compound::plain(" of total lines"),
        ];
        write_paragraph(&mut text, &comp, width, colors);
    }
    let filtered_bytes: u64 = hits.iter().map(|h| h.line.bytes_sent).sum();
    if !filters.is_empty() {
        let mut comp = vec![Compound::plain(" "), Compound::new("==>", BOLD), Compound::plain(" hits: ")];
        match key {
            Key::Hits => {
                comp.push(Compound::new(thousands(hits.len() as u64), ITALIC));
                comp.push(Compound::plain(format!(", bytes sent: {}", fit_4(filtered_bytes))));
            }
            Key::Bytes => {
                comp.push(Compound::plain(format!("{}, bytes sent: ", thousands(hits.len() as u64))));
                comp.push(Compound::new(fit_4(filtered_bytes), ITALIC));
            }
        }
        write_paragraph(&mut text, &comp, width, colors);
    }
    if !hits.is_empty() {
        let last_day = hits.iter().map(|h| h.day).max().unwrap();
        let n_days = last_day + 1;
        let mut global_per_day = vec![0u64; base.dates.len()];
        for h in &base.hits {
            global_per_day[h.day] += 1;
        }
        let total_hits = hits.len() as u64;
        let report = Report {
            hits,
            key,
            length,
            changes: matches.get_flag("changes"),
            all_paths: matches.get_flag("all"),
            width,
            colors,
            n_days,
            global_per_day,
            total_hits,
            dates: base.dates.clone(),
        };
        for field in &fields {
            match field {
                Field::Date => report.print_dates(&mut text),
                Field::Time => report.print_times(&mut text),
                Field::Method => report.print_methods(&mut text),
                Field::Status => report.print_status(&mut text),
                Field::Ip => report.print_ips(&mut text),
                Field::Referer => report.print_referers(&mut text),
                Field::Path => report.print_paths(&mut text),
            }
        }
    }
    out.write_all(text.as_bytes()).unwrap();
    out.flush().unwrap();
    let _ = Read::bytes(io::empty());
    Ok(())
}
