 7: ["100","200","300","400","500","600","700","710","720","721"],
}
import math, itertools
def rnd(kind, x):
    if kind=='floor': return math.floor(x+1e-9)
    if kind=='ceil': return math.ceil(x-1e-9)
    if kind=='round': return math.floor(x+0.5)
    if kind=='even':
        f=math.floor(x); d=x-f
        if abs(d-0.5)<1e-9: return f if f%2==0 else f+1
        return math.floor(x+0.5)
def seqprop(s, r, kind, leftover):
    n=len(s); red=[0]*n; rem=r; Srem=sum(s)
    for i in range(n):
        if Srem==0: break
        d=min(s[i], max(0, rnd(kind, rem*s[i]/Srem)), rem)
        red[i]=d; rem-=d; Srem-=s[i]
    order = range(n) if leftover=='first' else range(n-1,-1,-1)
    for i in order:
        x=min(s[i]-red[i], rem); red[i]+=x; rem-=x
    return red
def prop(s, r, kind, fix):
