    tot=sum(red)
    n=len(s)
    while tot>r:
        for i in (range(n-1,-1,-1) if fix in ('last','lf') else range(n)):
            if red[i]>0: red[i]-=1; tot-=1; break
    while tot<r:
        for i in (range(n) if fix in ('first','lf') else range(n-1,-1,-1)):
            if red[i]<s[i]: red[i]+=1; tot+=1; break
    return red
def check(f):
